<?php require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/upgrade.php'; require_admin_safe(); require_csrf(); $pdo=db();$m=$_SERVER['REQUEST_METHOD'];$d=json_input();
if($m==='GET')json_out(['ok'=>true,'items'=>$pdo->query('SELECT * FROM categories ORDER BY name')->fetchAll()]);
if($m==='POST'||$m==='PUT'){$id=(int)($d['id']??0);$name=clean_text($d['name']??'');$kind=clean_text($d['kind']??'all');$desc=clean_text($d['description']??'');if($name==='')json_out(['ok'=>false,'error'=>'نام دسته‌بندی الزامی است.'],422);$slug=preg_replace('/[^a-z0-9\-]+/i','-',strtolower(trim($name)))?:'cat-'.bin2hex(random_bytes(3));try{if($m==='POST'){$s=$pdo->prepare('INSERT INTO categories(name,slug,kind,description) VALUES(?,?,?,?)');$s->execute([$name,$slug,$kind,$desc]);$id=(int)$pdo->lastInsertId();}else{$s=$pdo->prepare('UPDATE categories SET name=?,kind=?,description=? WHERE id=?');$s->execute([$name,$kind,$desc,$id]);}json_out(['ok'=>true,'id'=>$id]);}catch(Throwable $e){json_out(['ok'=>false,'error'=>'این دسته‌بندی قبلاً ثبت شده یا اطلاعات نامعتبر است.'],422);}}
if($m==='DELETE'){ $id=(int)($d['id']??0);$pdo->prepare('DELETE FROM categories WHERE id=?')->execute([$id]);json_out(['ok'=>true]);}json_out(['ok'=>false,'error'=>'روش نامعتبر است.'],405);
